#include <stdlib.h>/' lib/core/strbuf.c && sed -i 's/    case TOK_COMMA:
        return syntax_error(t);/X/' lib/expr/parser.c && sed -i 's/^    case TOK_COMMA:$/    case TOK_COMMA:
    case TOK_END:/' lib/expr/parser.c && sed -n 58,75p lib/expr/parser.c && head -5 lib/core/strbuf.c

