gcc -std=c11 -Wall -Wextra -I'/tmp/stage/usr/my&pre/include' /tmp/u.c '/tmp/stage/usr/my&pre/lib/libqs.a' -lm -o /tmp/u && /tmp/u; make install DESTDIR=/tmp/st2 >/dev/null; grep prefix= /tmp/st2/usr/local/lib/pkgconfig/qs.pc; ls -R /tmp/st2/usr/local | head -30
